options.customCss:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --primary: #18263d;
  --primary-light: #263b5c;
  --accent: #c7a45b;
  --bg: #f4f5f7;
  --card: #ffffff;
  --text: #18202d;
  --muted: #6b7280;
  --border: #e1e5eb;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background:
    radial-gradient(circle at top left, rgba(199,164,91,.12), transparent 35%),
    linear-gradient(135deg, #f7f7f6 0%, #eef1f5 100%);
  font-family: 'Inter', sans-serif !important;
  color: var(--text);
}

form {
  max-width: 650px !important;
  margin: 45px auto !important;
  padding: 42px !important;
  background: rgba(255,255,255,.96) !important;
  border-radius: 22px !important;
  box-shadow: 0 20px 60px rgba(24,38,61,.12) !important;
  border: 1px solid rgba(24,38,61,.07) !important;
}

h1 {
  color: var(--primary) !important;
  font-size: 30px !important;
  font-weight: 700 !important;
  letter-spacing: -0.6px;
  margin-bottom: 10px !important;
}

form > div:first-child::after {
  content: "Tell us what you're looking for and we'll help you find the right property.";
  display: block;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
  margin-bottom: 30px;
}

label {
  color: var(--primary) !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  margin-bottom: 9px !important;
}

input,
select,
textarea {
  width: 100% !important;
  background: #fafbfc !important;
  border: 1px solid var(--border) !important;
  border-radius: 11px !important;
  padding: 14px 15px !important;
  font-family: 'Inter', sans-serif !important;
  font-size: 14px !important;
  color: var(--text) !important;
  transition: all .2s ease !important;
}

input:hover,
select:hover,
textarea:hover {
  border-color: #bdc5d1 !important;
}

input:focus,
select:focus,
textarea:focus {
  outline: none !important;
  border-color: var(--accent) !important;
  box-shadow: 0 0 0 3px rgba(199,164,91,.13) !important;
  background: #fff !important;
}

button[type="submit"] {
  width: 100% !important;
  margin-top: 15px !important;
  padding: 15px 20px !important;
  border: none !important;
  border-radius: 11px !important;
  background: linear-gradient(135deg, var(--primary), var(--primary-light)) !important;
  color: white !important;
  font-family: 'Inter', sans-serif !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  transition: all .25s ease !important;
  box-shadow: 0 8px 20px rgba(24,38,61,.18) !important;
}

button[type="submit"]:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 26px rgba(24,38,61,.24) !important;
}

button[type="submit"]:active {
  transform: translateY(0);
}

small,
p {
  color: var(--muted);
}

@media (max-width: 700px) {
  form {
    margin: 15px !important;
    padding: 28px 22px !important;
    border-radius: 18px !important;
  }

  h1 {
    font-size: 25px !important;
  }
}

parameters.jsCode:
const scores = {
  propertyType: {
    Apartment: 10,
    Villa: 15,
    Commercial: 10
  },
  buyOrRent: {
    Buy: 15,
    Rent: 5
  },
  newOrResale: {
    New: 10,
    Resale: 10
  },
  firstPurchase: {
    Yes: 5,
    No: 10
  },
  timeline: {
    Immediately: 20,
    "Within 1 month": 15,
    "1–3 months": 10,
    "3–6 months": 5,
    "6+ months": 0
  },
  budget: {
    "Above $1,000,000": 20,
    "$700,000–$1,000,000": 15,
    "$400,000–$700,000": 10,
    "$200,000–$400,000": 5,
    "Below $200,000": 0
  }
};

const score =
  scores.propertyType[$json["Property Type"]] +
  scores.buyOrRent[$json["Buy or Rent"]] +
  scores.newOrResale[$json["New or Resale"]] +
  scores.firstPurchase[$json["First Property Purchase"]] +
  scores.timeline[$json["Timeline"]] +
  scores.budget[$json["Budget Range"]];

return {
  ...$json,
  score
};

